bool ScriptSession::damageUnit(std::uint32_t source,std::uint32_t target,float amount,unsigned attackType,unsigned damageType,bool attack,bool ranged,float* dealt,bool deflected,bool useEtherealBonus,std::optional<unsigned> orphanOwner,bool redistributed) {
    if(dealt)*dealt=0;if(!std::isfinite(amount) || amount<0 || amount>1000000000)throw std::runtime_error("Damage amount outside supported range");if(attackType>6 || (damageType!=0 && damageType!=4 && damageType!=5 && (damageType<8 || damageType>26)))throw std::runtime_error("Unknown damage classification");if((!alive(source,NativeKind::Unit) && !orphanOwner) || !alive(target,NativeKind::Unit))return false;if(orphanOwner && *orphanOwner>=16)throw std::runtime_error("Invalid retained periodic damage owner");auto from=alive(source,NativeKind::Unit)?units_.at(source):std::shared_ptr<UnitState>{},to=units_.at(target);if(!from)source=0;auto damageOwner=from?from->owner:orphanOwner.value_or(UINT_MAX);if(to->swarmAgent || capability(*to,"Aloc") || to->impaledAir() || to->sleepProtected() || to->cycloned())return false;if((from && from->removing) || to->removing || to->invulnerable || to->phaseShifted() || to->mirrorImage || to->spiritSplit || (to->lavaSpawn && to->lavaSpawn->emerging) || (to->transport && !(to->digestion && source==to->transport)) || capability(*to,"Avul") || number(to->life)<=0)return false;if(capability(*to,"Amim") && damageType!=26 && (attackType==4 || (damageType>=8 && damageType<=20) || damageType==23 || damageType==25))return false;if(attack && !redistributed && !deflected && amount>0 && from){auto death=to->deathRevision;if(phaseShiftReaction(target,source) || !alive(target,NativeKind::Unit) || to->removing || to->deathRevision!=death || number(to->life)<=0 || !alive(source,NativeKind::Unit) || from->removing || from->owner!=damageOwner)return false;}double damage=redistributed?amount:double(amount)*(from?from->damageDealt:1)*to->damageTaken;if(to->ethereal() && damageType!=26){std::stringstream table(gameplay().value("Misc","EtherealDamageBonus"));std::vector<float> factors;std::string part;while(std::getline(table,part,',')){float factor=std::stof(part);if(!std::isfinite(factor) || factor<0 || factor>100)throw std::runtime_error("Invalid source ethereal damage factor");factors.push_back(factor);}if(factors.size()!=7)throw std::runtime_error("Missing source ethereal damage factors");constexpr unsigned slots[]={5,0,1,2,3,4,6};float factor=factors[slots[attackType]];if(factor==0)return false;if(factor>1 && !useEtherealBonus)factor=1;if(factor>1 && (damageOwner>=16 || !enemy(damageOwner,to->owner)) && gameplayNumber("EtherealDamageBonusAlly",0)==0)factor=1;damage*=factor;}
    if(damageType!=26){auto& data=definitions();auto defense=data.field(to->type,"UnitBalance","defType","normal");constexpr const char* armorTypes[]={"small","medium","large","fort","normal","hero","divine","none"};unsigned armor=8;for(unsigned i=0;i<8;++i)if(defense==armorTypes[i])armor=i;if(to->roots && to->roots->uprooted)armor=to->roots->spell.uprootedDefense;if(armor==8)throw std::runtime_error("Unknown source defense type: "+defense);constexpr const char* attacks[]={"Spells","Normal","Pierce","Siege","Magic","Chaos","Hero"};auto key=std::string("DamageBonus")+attacks[attackType];std::stringstream sourceTable(gameplay().value("Misc",key));std::string part;std::vector<float> factors;while(std::getline(sourceTable,part,',')){auto factor=std::stof(part);if(!std::isfinite(factor) || factor<0)throw std::runtime_error("Invalid source attack factor");factors.push_back(factor);}if(factors.size()!=8)throw std::runtime_error("Missing source attack/defense factors: "+key);damage*=factors[armor];if(damageType==4){float defensePoints=data.number(to->type,"UnitBalance","def")+to->technology.armor+to->equipment.armor;if(to->hero)defensePoints+=to->appliedHeroStats[1]*gameplayNumber("AgiDefenseBonus",.3f)+gameplayNumber("AgiDefenseBase",-2);auto carapace=spikedCarapace(*to);if(carapace && attack && !ranged)damage*=carapace->secondary;defensePoints=defensePoints*(1+to->aura.armorPercent)+to->aura.armor+to->spellBonus(&UnitBuff::armor)+(carapace?carapace->bonus:0);double coefficient=gameplayNumber("DefenseArmor",.06f);if(coefficient<=0 || coefficient>=1)throw std::runtime_error("Unsupported armor coefficient");damage*=defensePoints>=0?1/(1+coefficient*defensePoints):2-std::pow(1-coefficient,-defensePoints);}}
    bool spellDamage=damageType!=26 && (attackType==4 || (!attack && damageType!=4 && damageType!=5));if(!redistributed && damageType!=26)damage=defensePassiveDamage(*to,float(damage),attackType,attack,ranged,spellDamage,damageOwner);if(spellDamage)damage*=std::max(0.f,1-to->equipment.spellReduction);if(spellDamage)for(auto it=to->buffs.begin();it!=to->buffs.end();){auto& b=it->second;if(b.kind==BuffKind::Shell && !b.magicImmune){damage*=std::max(0.f,1-b.spellReduction);if(b.shield>0){float absorb=std::min(float(damage),b.shield);b.shield-=absorb;damage-=absorb;if(b.shield<=0){releaseBuff(b);it=to->buffs.erase(it);continue;}}}++it;}
    if(!redistributed){damage*=1+to->spellBonus(&UnitBuff::damageTakenBonus);for(auto& [id,b]:to->buffs)if(b.kind==BuffKind::PossessionCaster)damage*=b.damageTakenFactor;if(attack && from)for(auto& [id,b]:from->buffs)if(b.kind==BuffKind::Defend)damage*=b.attackFactor;}
    for(auto& [id,b]:to->buffs){if((b.kind==BuffKind::Avatar || b.kind==BuffKind::Bladestorm) && spellDamage)damage*=b.magicFactor;if(b.kind==BuffKind::Defend){if(attack && ranged && attackType==2)damage*=deflected?b.deflectPierce:b.pierceFactor;else if(deflected && attack && ranged && attackType==4)damage*=b.deflectMagic;else if(spellDamage)damage*=b.magicFactor;}}
    if(damageType!=26)for(auto it=to->buffs.begin();it!=to->buffs.end();){auto& b=it->second;if(b.kind!=BuffKind::ManaShield){++it;continue;}float absorbed=std::min(float(damage)*b.absorbFraction,number(to->mana)*b.manaEfficiency);to->mana=real(std::max(0.f,number(to->mana)-absorbed/b.manaEfficiency));damage-=absorbed;if(number(to->mana)<=0){releaseBuff(b);it=to->buffs.erase(it);}else ++it;}
    if(!std::isfinite(damage) || damage>1000000000)throw std::runtime_error("Final damage outside supported range");if(!redistributed && damage>0){auto revision=to->deathRevision;damage=spiritLinkDamage(source,target,float(damage),damageOwner);if(!alive(target,NativeKind::Unit) || to->removing || to->deathRevision!=revision || number(to->life)<=0)return true;}if(damage>0 && damageOwner<16 && enemy(damageOwner,to->owner))for(auto it=to->buffs.begin();it!=to->buffs.end();)if(it->second.breakOnDamage){releaseBuff(it->second);it=to->buffs.erase(it);}else ++it;auto deathRevision=to->deathRevision;ScriptContext context;context.damageSource=source;context.damageAttack=attack;context.damageRanged=ranged;context.damage=real(float(damage));unitEvent(target,UINT_MAX,52,context);if(alive(target,NativeKind::Unit) && !to->removing && to->deathRevision==deathRevision && number(to->life)>0){if(damage>0)wakeUnit(target);if(dealt)*dealt=std::min(number(to->life),float(damage));unitLife(runtime_.handle("unit",target),real(std::max(0.f,number(to->life)-float(damage))),source);}return true;
}
void ScriptSession::bindDamageNatives() {
    bind("UnitDamageTarget","boolean",{"unit","widget","real","boolean","boolean","attacktype","damagetype","weapontype"},[this](auto& vm,auto a){if(a[1].bits && !alive(a[1].bits,NativeKind::Unit))throw std::runtime_error("Damage to non-unit widgets is not implemented");return vm.boolean(damageUnit(a[0].bits,a[1].bits,number(jass::Real::fromBits(a[2].bits)),a[5].bits,a[6].bits,a[3].bits!=0,a[4].bits!=0));});
    bind("GetEventDamage","real",{},[this](auto& vm,auto){return vm.real(contexts_.empty()?jass::Real{}:contexts_.back().damage);});
    bind("GetEventDamageSource","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().damageSource);});
}
